{
  "title": "The Bridge Out of the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small team studies a map at the edge of the dead city.",
      "visual_description": "Dusk on a windswept ridge overlooking a ruined royal city; torn banners flap in the distance. Three figures crouch around a weathered map spread on a flat stone.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 2,
      "caption": "The scout points out the castle gates far below.",
      "visual_description": "Wide shot of a cracked stone gatehouse with broken portcullis, framed by the scout's outstretched arm in the foreground.",
      "characters": ["scout", "map_reader"]
    },
    {
      "scene_number": 3,
      "caption": "They slip past a frightened cluster of townspeople.",
      "visual_description": "A narrow rubble-strewn lane; hooded villagers huddle under a collapsed awning, eyes wide as the team passes in shadow.",
      "characters": ["scout", "magic_helper", "frightened_villager"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol marches by on the main avenue.",
      "visual_description": "Iron-helmed soldiers in faded royal tabards stomp past a fountain choked with weeds; the team presses flat against a broken column.",
      "characters": ["armored_patrol_leader", "map_reader", "scout"]
    },
    {
      "scene_number": 5,
      "caption": "A sleepy city official mumbles useful rumors.",
      "visual_description": "Interior of a leaning records-house lit by one candle; a yawning official in a too-big robe leans over a ledger, finger tracing a tower symbol.",
      "characters": ["sleepy_official", "map_reader"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon drift up from the lower districts.",
      "visual_description": "A smoking chasm between collapsed houses; far below, a long serpentine shadow curls against red coals. The scout peers down from a broken rail.",
      "characters": ["scout", "magic_helper"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower glows against the bruised sky.",
      "visual_description": "A tall black tower webbed in violet light, leaning slightly; the team stands small in the foreground, silhouetted against its glow.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "The magic helper warns about a sealed door inside.",
      "visual_description": "Close-up of the magic helper's hands tracing glowing runes in the air; faint reflections of the symbols shine in the scout's eyes.",
      "characters": ["magic_helper", "scout"]
    },
    {
      "scene_number": 9,
      "caption": "Old royal banners hang in a forgotten hall.",
      "visual_description": "Long dust-filled hall lined with tattered banners bearing a crown-and-bridge sigil; the team walks single-file down a moonlit shaft of light.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "An armored patrol blocks the inner stair.",
      "visual_description": "Two guards in plate armor with crossed halberds at the foot of a curving stair; the scout raises empty hands, stalling them.",
      "characters": ["scout", "armored_patrol_leader", "armored_patrol_soldier"]
    },
    {
      "scene_number": 11,
      "caption": "The magic helper opens the first sealed door.",
      "visual_description": "A heavy iron door inscribed with runes splits open in a ripple of pale blue light; the helper's staff trembles with effort.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "They find the prisoner chained in a cold cell.",
      "visual_description": "A small round chamber high in the tower; a slumped figure in fine torn clothes is chained to a stone ring, looking up as light spills in.",
      "characters": ["map_reader", "magic_helper", "captive_noble"]
    },
    {
      "scene_number": 13,
      "caption": "The scout breaks the chains with a quick stroke.",
      "visual_description": "Sparks fly as a short blade cracks an iron link; the captive winces, freed wrist held by the scout.",
      "characters": ["scout", "captive_noble"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm bells ring across the dead city.",
      "visual_description": "View from the tower window: distant bell-towers swing, torches kindle along rooftops, and the patrol pours toward the tower base.",
      "characters": ["magic_helper", "captive_noble", "armored_patrol_leader"]
    },
    {
      "scene_number": 15,
      "caption": "The team flees through a second magic door.",
      "visual_description": "A glowing archway carved into a tower wall opens onto open sky; the team leaps through as runes flare and fade behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "captive_noble"]
    },
    {
      "scene_number": 16,
      "caption": "A dragon's roar shakes the rooftops above them.",
      "visual_description": "Rooftop chase scene: tiles scatter as an enormous winged shadow sweeps overhead, fire glinting off the scout's drawn blade.",
      "characters": ["scout", "captive_noble", "city_dragon"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the long bridge at the city's edge.",
      "visual_description": "A high stone bridge stretching over a misty gorge; the bridge mouth is framed by twin broken statues of crowned kings. The team sprints onto it.",
      "characters": ["map_reader", "scout", "magic_helper", "captive_noble"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses to safety as the bridge collapses behind them.",
      "visual_description": "Far side of the gorge at dawn; the team stands among soft grass and wildflowers while the bridge crumbles into mist, the cursed tower glowing small and far.",
      "characters": ["map_reader", "scout", "magic_helper", "captive_noble"]
    }
  ]
}

